class Coupon:
    def __init__(self):
        self.state = 'unused'
    def use(self, kind):
        if self.state == 'unused' and kind == 'partial':
            self.state = 'partial'
        elif self.state == 'unused' and kind == 'full':
            self.state = 'used'
        else:
            raise ValueError('invalid')
        return self.state
